    /// <summary>
    /// Checks the validity of an invite link for a chat folder and returns information about the corresponding chat folder
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatFolderInviteLinkInfo> CheckChatFolderInviteLinkAsync(string inviteLink = default)
    {

           using var activity =  StartCallActivity("CheckChatFolderInviteLinkAsync", typeof(CheckChatFolderInviteLink).FullName ?? "CheckChatFolderInviteLinkAsync");

           try
           {
             return client.CheckChatFolderInviteLinkAsync(inviteLink);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
